from math import sqrt, sin, cos, pi
from random import Random
a=1/sqrt(2)
X=[[0,1],[a,0],[a,0]]
A=[[0,-1],[-1,-1.5],[-1,1.5]]
def F(Y):
    return sum(abs(Y[i][j])+A[i][j]*Y[i][j] for i in range(3) for j in range(2))
def update(B,V):
    Y=[row[:] for row in X]
    for i in range(2):
        for j in range(2):
            Y[B[i]][j]=sum(V[i][z]*X[B[z]][j] for z in range(2))
    return Y
print('F(X):',F(X))
print('Columns orthonormal:',[[sum(X[i][j]*X[i][k] for i in range(3)) for k in range(2)] for j in range(2)])
for B in [(0,1),(0,2),(1,2)]:
    best=(F(X),'identity',0)
    for i in range(10001):
        theta=2*pi*i/10000
        c,s=cos(theta),sin(theta)
        for label,V in [('rotation',[[c,s],[-s,c]]),('reflection',[[-c,s],[s,c]])]:
            val=F(update(B,V))
            if val<best[0]:best=(val,label,theta)
    print('Pair',tuple(b+1 for b in B),'minimum over both O(2) components:',best)
for t in [0.001,0.01,0.1]:
